import { Component, computed, input } from '@angular/core';

/** hrm-amount-cell — ô số tiền/số lượng, canh phải, phân tách nghìn (Intl).
 *  signed=true → hiện dấu +/− và tô màu (dương=lục, âm=đỏ) cho cột biến động. */
@Component({
  selector: 'hrm-amount-cell',
  template: `<span class="am-val">{{ display() }}</span>`,
  host: { class: 'hrm-amount-cell', '[attr.data-sign]': 'signClass()' },
  styles: [`
:host { display: block; text-align: right; font-variant-numeric: tabular-nums;
  font-size: var(--fs-14); color: var(--text-strong); }
:host([data-sign='pos']) .am-val { color: var(--success-base); }
:host([data-sign='neg']) .am-val { color: var(--error-base); }
  `],
})
export class HrmAmountCell {
  readonly value = input(0);
  /** Đơn vị hậu tố (VD '₫', '$', 'giờ'). '' = không hiện. */
  readonly currency = input('');
  /** Hiện dấu +/− và tô màu tăng/giảm. */
  readonly signed = input(false);
  readonly decimals = input(0);
  readonly locale = input('vi-VN');

  protected readonly display = computed(() => {
    const v = this.value();
    const n = new Intl.NumberFormat(this.locale(), {
      minimumFractionDigits: this.decimals(),
      maximumFractionDigits: this.decimals(),
    }).format(Math.abs(v));
    const sign = this.signed() ? (v > 0 ? '+' : v < 0 ? '−' : '') : v < 0 ? '−' : '';
    const cur = this.currency() ? ` ${this.currency()}` : '';
    return `${sign}${n}${cur}`;
  });
  protected readonly signClass = computed(() =>
    this.signed() ? (this.value() > 0 ? 'pos' : this.value() < 0 ? 'neg' : null) : null,
  );
}
